    {'ll': [-73.5817, 43.1], 'label': 'Saratoga (approx.)', 'date': 'Oct 1777', 'acc': True, 'big': True, 'dy': -8, 'plate': {'kicker': 'US1.10 · 1777-78', 'title': 'Saratoga and the French alliance', 'sub': 'October 1777 to February 1778', 'text': "[[c-us-war-saratoga]] [[c-us-war-alliance]]", 'sources': ['us1c-brit-saratoga', 'us1c-oh-alliance']}},
