    {'ll': [-76.8075, 42.0897], 'label': 'Newtown (approx.)', 'date': '29 Aug 1779', 'acc': True, 'anchor': 'end', 'dy': 16, 'plate': {'kicker': 'US1.10 · Native nations', 'title': 'The Haudenosaunee divided', 'sub': '1779', 'text': "[[c-us-war-haud]] [[c-us-war-calloway]]", 'sources': ['us1c-abt-newtown', 'us1c-ia-calloway']}},
    {'ll': [-76.5089, 37.2383], 'label': 'Yorktown', 'date': 'Oct 1781', 'acc': True, 'big': True, 'dy': 16, 'plate': {'kicker': 'US1.10 · 1781-83', 'title': 'Yorktown and the peace', 'sub': 'October 1781 to September 1783', 'text': "[[c-us-war-yorktown]] [[c-us-war-paris]] [[c-us-war-treaty]]", 'sources': ['us1c-brit-yorktown', 'us1c-nps-yorktown', 'us1c-oh-alliance', 'us1c-oh-treaty', 'us1c-avalon-paris']}},
